  ["81327757c9ec8d35"] = { "Brzzzzt!\n\n<Benvenuto/Benvenuta> al Matrix Punchograph 3005 barra B, un terminale di livello di sicurezza beta.\n\nRilevata scheda perforata gialla. Accesso consentito.\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001", "." },
  ["81391daf5e9bd197"] = { "Oh, ⟦Darrowshire=Borgo di Darrow⟧! Darei mille vite per te!", "." },
  ["8139d78abbcbbd60"] = { "Chi riceve un ⟦Horde Commendation Signet=Anello d'Encomio dell'Orda⟧ è <un/una> <eroe/eroina> che va ben oltre il proprio dovere verso l'⟦Horde=Orda⟧. In tutte le capitali si trovano vari ufficiali dell'encomio per le fazioni dell'⟦Horde=Orda⟧: parla con quello della fazione con cui vuoi aumentare la reputazione, e dagli il numero di anelli che ti chiede!\n\nA proposito, durante lo sforzo bellico qui, se per i tuoi anelli preferisci una ricompensa materiale invece della reputazione, cerca il signore della guerra Gorchuk.", "." },
  ["813bdb9e9af354b1"] = { "Perché sei ancora <vivo/viva> e le mie mani non sono strette attorno al tuo tozzo collo.", "." },
  ["814dedf113e9c02c"] = { "La rabbia che ti brucia dentro troverà presto alimento nei nostri nemici.", "." },
  ["81583f70f34b8885"] = { "L'invenzione, <mio/mia> <caro/cara> {class}, è per il due percento ispirazione in bottiglia, per il quattro percento esposizione solare, per il sei percento probabilità di temporali in diradamento entro metà pomeriggio, e per il novantatré percento Rumplesnicker.\n\nAspetta, fa cento? Ho i miei appunti qui da qualche parte.", "." },
  ["8162bed7f086b8d2"] = { "Questo Dimensional Imploder sembra pericoloso! Come posso costruirne uno?", "." },
  ["816f8b0e4261e1bc"] = { "Ciao! Mi chiamo Jenna! E tu?", "." },
  ["8199922a929fb6c3"] = { "Non dobbiamo cedere al male che ha oscurato la nostra terra. I Guardiani della Notte devono prevalere!", "." },
  ["81aa5c14c36e7b77"] = { "Questa storia ti piacerà, {race}. Vedi, il punto è questo. Non appena Malygos mi ha incaricato di proteggere il frammento dello scettro, ho capito che mi aspettava un'eternità di mal di testa e sofferenze.\n\nTutto ciò che voglio è studiare queste coste ricche di magia e scoprire quali manufatti possano essere rimasti dalla Separazione. Sai, un tempo qui prosperava una civiltà degli ⟦Highborne=Alti Nobili⟧! Non c'è bisogno che tu mi dica che qui intorno ci saranno oggetti magici di tutto rispetto, {race}. Ne sento l'odore!", "." },
  ["81abfaca788c5358"] = { "Salsicciotti di Lunacupa appena tolti dalla griglia. Venite a prenderli finché sono caldi!", "." },
  ["81b399b47c55378d"] = { "...Nove...Dieci... Pronti o no, arrivo!", "." },
